function valid(k){if(k==='activation'&&+state.activation>=7&&!state.grounding){toast('Choose a grounding practice before continuing');return false}if(k==='activation'&&state.grounding==='other'&&!String(state.customGrounding||'').trim()){toast('Describe the grounding practice you want to use');return false}if(k==='story'&&(state.emotionThemes||[state.emotionTheme].filter(Boolean)).includes('Other / write my own')&&!String(state.customEmotionTheme||'').trim()){toast('Write the broader theme that feels connected');return false}if(k==='capacity'&&(!state.presentSafety||!state.threatSource||!state.stateDuration||!(state.signalFunctions||[state.defenseFunction].filter(Boolean)).length||!(state.resistantEmotions||[]).length||!state.replayImpact||!state.beliefGrip)){toast('Complete each safety and orientation check to continue');return false}if(k==='capacity'&&(state.signalFunctions||[state.defenseFunction].filter(Boolean)).includes('other')&&!String(state.defenseCustom||'').trim()){toast('Describe what the feeling may be signaling');return false}if(k==='emotion'&&!String(state.situation||'').trim()){toast('Describe the state you find yourself in');return false}if(k==='emotion'&&!(state.emotions||[]).length){toast('Choose at least one emotion to continue');return false}if(k==='emotion'&&(state.emotions||[]).includes('other')&&!String(state.customEmotion||'').trim()){toast('Name the other emotion you are feeling');return false}if(k==='urge'&&!(state.urges||[]).length){toast('Choose at least one urge to continue');return false}if(k==='urge'&&(state.urges||[]).includes('other')&&!String(state.customUrge||'').trim()){toast('Describe the other urge you are noticing');return false}if(k==='response'&&!(state.responseValues||[state.responseValueChoice].filter(Boolean)).length&&!String(state.value||'').trim()){toast('Choose or write a value for your response');return false}if(k==='response'&&(state.responseValues||[state.responseValueChoice].filter(Boolean)).includes('Other / write my own')&&!String(state.value||'').trim()){toast('Write the value you want your response to reflect');return false}if(k==='lens'&&!(state.lensReframes||[]).length&&!String(state.alternate||'').trim()){toast('Choose or write at least one wider perspective');return false}if(k==='lens'&&!String(state.balanced||'').trim()){toast('Write a whole-truth statement before continuing');return false}const req={situation:'situation',story:'story',balanced:'balanced',response:'response',outcome:'outcome'}[k];if(req&&!String(state[req]||'').trim()){toast(k==='urge'?'Choose one option to continue':'Add a short response to continue');return false}if(k==='evidence'&&!(state.personalStrengths||[]).length){toast('Choose at least one personal strength to carry forward');return false}if(k==='evidence'&&!(state.carryValues||[]).length){toast('Choose at least one value to keep in awareness');return false}if(k==='evidence'&&(state.personalStrengths||[]).includes('Other / write my own')&&!String(state.customStrength||'').trim()){toast('Write the personal strength you want to carry');return false}if(k==='evidence'&&(state.carryValues||[]).includes('Other / write my own')&&!String(state.customCarryValue||'').trim()){toast('Write the value you want to carry');return false}if(k==='evidence'&&!(state.stabilitySupports||[]).length&&!String(state.facts||'').trim()){toast('Choose or describe something steady, supportive, or within your control');return false}if(k==='evidence'&&!state.unknownStatus){toast('Choose whether there is information that is unknown');return false}if(k==='evidence'&&state.unknownStatus==='yes'&&!(state.unknownTypes||[]).length&&!String(state.unknowns||'').trim()){toast('Describe what information is unknown');return false}if(k==='evidence'&&!state.mistreatment){toast('Choose whether a boundary may have been crossed');return false}return true}
function persist(){if(state.previewMode){toast('Preview closed without saving');return}if(state.saved&&!state.editingId)return;const all=sessions(),editingId=state.editingId;state.id=editingId||state.id||Date.now();state.emotionNames=(state.emotions||[state.emotion]).map(id=>id==='other'&&state.customEmotion?'Other: '+state.customEmotion:EMOTIONS[id]?.name).filter(Boolean);state.emotionName=state.emotionNames.join(', ');state.urgeNames=(state.urges||[state.urge]).map(id=>id==='other'&&state.customUrge?'Other: '+state.customUrge:URGES[id]).filter(Boolean);state.saved=true;delete state.editingId;const updated=editingId?all.map(s=>String(s.id)===String(editingId)?state:s):[state,...all];saveSessions(updated.slice(0,100));localStorage.removeItem(DRAFT)}

function renderStories(){const ss=sessions();if(!ss.length){app.innerHTML=`<section class="profile-head"><div><div class="eyebrow">Your learning profile</div><h1 class="page-title">My Stories</h1></div></section><div class="card empty"><div class="empty-icon">○</div><h3>Your patterns will appear here.</h3><p class="subtle">Complete a few reflections to notice recurring emotions, stories, urges, responses, and outcomes.</p><br><button class="btn" id="firstReflection">Start a reflection</button></div>`;document.querySelector('#firstReflection').onclick=startFlow;return}const frequency=(getValues)=>{const counts={};ss.forEach(s=>getValues(s).filter(Boolean).forEach(value=>counts[value]=(counts[value]||0)+1));return Object.entries(counts).sort((a,b)=>b[1]-a[1])};const emotionValues=s=>s.emotionNames||s.emotions?.map(id=>id==='other'&&s.customEmotion?'Other: '+s.customEmotion:EMOTIONS[id]?.name).filter(Boolean)||[s.emotionName].filter(Boolean);const urgeValues=s=>s.urgeNames||s.urges?.map(id=>id==='other'&&s.customUrge?'Other: '+s.customUrge:URGES[id]).filter(Boolean)||[URGES[s.urge]].filter(Boolean);const topEmotion=frequency(emotionValues)[0]||['—',0],topUrge=frequency(urgeValues)[0]||['—',0];const rated=ss.filter(s=>s.afterIntensity),shift=rated.length?Math.round(rated.reduce((n,s)=>n+((+s.intensity||0)-(+s.afterIntensity||0)),0)/rated.length*10)/10:null;const patterns={};ss.forEach(s=>{const emotions=emotionValues(s).join(', '),urges=urgeValues(s).join(', '),theme=[...(s.emotionThemes||[s.emotionTheme].filter(Boolean)).filter(x=>x!=='Other / write my own'),s.customEmotionTheme].filter(Boolean).join(', ')||Object.values(s.beliefs||{}).flatMap(v=>Array.isArray(v)?v:[v]).filter(Boolean)[0]||s.story||'Theme still emerging',key=`${emotions}|${theme}|${urges}`;if(!patterns[key])patterns[key]={...s,emotions,urges,theme,count:0};patterns[key].count++});const recurring=Object.values(patterns).sort((a,b)=>b.count-a.count).slice(0,4);app.innerHTML=`<section class="profile-head"><div><div class="eyebrow">Your learning profile</div><h1 class="page-title">My Stories</h1><p class="subtle">Patterns are observations, not labels.</p></div><button class="btn" id="newReflection">New reflection</button></section><section class="insight-grid"><article class="card insight"><span class="label">Most frequent emotion</span><strong>${escapeHTML(topEmotion[0])}</strong><span class="pill">noticed ${topEmotion[1]}×</span></article><article class="card insight"><span class="label">Common urge</span><strong>${escapeHTML(topUrge[0])}</strong><span class="pill">noticed ${topUrge[1]}×</span></article><article class="card insight"><span class="label">Average intensity shift</span><strong>${shift===null?'—':`${shift>0?'−':shift<0?'+':''}${Math.abs(shift)} points`}</strong><span class="subtle">${rated.length?'after strategy follow-up':'No follow-ups yet'}</span></article></section><section class="card"><div class="eyebrow">Recurring pathways</div><h3>Trigger → emotion → theme → urge → response → outcome</h3>${recurring.map(p=>`<article class="pathway"><div class="pathway-head"><strong>${escapeHTML(p.emotions)}</strong>${p.count>1?`<span class="pill">${p.count}×</span>`:''}</div><div class="pathway-grid"><div><span>Trigger</span><p>${escapeHTML(p.situation||'—')}</p></div><div><span>Theme</span><p>${escapeHTML(p.theme)}</p></div><div><span>Urges</span><p>${escapeHTML(p.urges||'—')}</p></div><div><span>Response</span><p>${escapeHTML(p.response||p.action||'—')}</p></div><div><span>Intended outcome</span><p>${escapeHTML(p.outcome||'—')}</p></div></div></article>`).join('')}</section><section class="card" style="margin:20px 0 50px"><div class="eyebrow">Reflection history</div><h3>Recent sessions</h3>${ss.map(s=>`<div class="session-row"><time>${new Date(s.date).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</time><div><strong>${escapeHTML(emotionValues(s).join(', '))} · ${s.intensity}/10${s.afterIntensity?` → ${s.afterIntensity}/10 after follow-up`:' · follow-up pending'}</strong><p>${escapeHTML(s.situation)}</p></div><button class="btn ghost" data-view="${s.id}">${s.afterIntensity?'View / update':'Follow up'}</button></div>`).join('')}</section>`;document.querySelector('#newReflection').onclick=startFlow;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>viewSession(b.dataset.view))}
function viewSession(id){const s=sessions().find(x=>String(x.id)===String(id));if(!s)return;const rating=s.afterIntensity||s.intensity||5;showModal(`<div class="eyebrow">Saved reflection · ${new Date(s.date).toLocaleDateString()}</div><h2>${escapeHTML(s.emotionName||'Reflection')} · ${s.intensity}/10${s.afterIntensity?` → ${s.afterIntensity}/10 after follow-up`:' · follow-up pending'}</h2>${sessionSummaryMarkup(s)}<section class="summary-section"><h3>Return and learn</h3><p class="subtle">Complete this after you have had time to use—or decide not to use—the strategy. You can return and update it again later.</p><div class="field"><label>How intense do the emotions feel now?</label><div class="range-row"><span>Low</span><input id="followUpIntensity" type="range" min="1" max="10" value="${rating}"><span>High</span><output class="range-value" id="followUpIntensityValue">${rating}</output></div></div><div class="field"><label>What strategy or response did you try?</label><textarea id="followUpWhatTried" rows="3" placeholder="What I tried, changed, delayed, communicated, or chose not to do…">${escapeHTML(s.followUpWhatTried||'')}</textarea></div><div class="field"><label>What happened, changed, or became clearer?</label><textarea id="followUpOutcome" rows="4" placeholder="I noticed… It helped by… It did not help because… What I learned is…">${escapeHTML(s.followUpOutcome||'')}</textarea></div><div class="step-actions"><button class="btn secondary" id="reviseReflection">Revise full reflection</button><button class="btn" id="saveFollowUp">Save follow-up</button></div></section>`);document.querySelector('#followUpIntensity').oninput=e=>document.querySelector('#followUpIntensityValue').textContent=e.target.value;document.querySelector('#saveFollowUp').onclick=()=>saveFollowUp(id);document.querySelector('#reviseReflection').onclick=()=>reviseReflection(id)}
function saveFollowUp(id){const all=sessions(),index=all.findIndex(s=>String(s.id)===String(id));if(index<0)return;all[index]={...all[index],afterIntensity:+document.querySelector('#followUpIntensity').value,followUpWhatTried:document.querySelector('#followUpWhatTried').value.trim(),followUpOutcome:document.querySelector('#followUpOutcome').value.trim(),followUpDate:new Date().toISOString()};saveSessions(all);modal.close();toast('Follow-up saved');if(route==='stories')renderStories()}
function reviseReflection(id){const s=sessions().find(x=>String(x.id)===String(id));if(!s)return;state={...s,editingId:s.id,saved:false};route='flow';step=1;modal.close();renderFlow();window.scrollTo({top:0,behavior:'smooth'})}setRoute('home');
